//! Embedding state of chunks, pages and takes (`gbrain_store::embeddings`).
//!
//! One `#[napi] impl Brain` block per family file; `families/mod.rs` lists every family once.
//! Each method decodes its arguments, runs one `Store` call on the pool through `Brain::run`,
//! and resolves plain JSON. Vectors travel as number arrays; the TypeScript members turn them
//! into `Float32Array`s and the id lists into `Map`s.
//!
//! Built by the core store work; other families do not edit this file.

use napi::Env;
use napi::bindgen_prelude::Object;
use napi_derive::napi;
use serde_json::Value;

use crate::store_binding::{Brain, arg, required};
use gbrain_store::embeddings::TakeEmbeddingInput;

#[napi]
impl Brain {
    /// `getEmbeddingsByChunkIds(ids)`: `[{ id, embedding }]` for the visible chunks of sealed
    /// pages that have a vector.
    #[napi]
    pub fn get_embeddings_by_chunk_ids<'env>(
        &self,
        env: &'env Env,
        ids: Value,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            let ids: Vec<u64> = required(ids, "getEmbeddingsByChunkIds ids")?;
            s.get_embeddings_by_chunk_ids(&ids)
        })
    }

    /// `cosinesByChunkIds(ids, query)`: `[{ id, cosine }]` for the served chunks with a vector.
    #[napi]
    pub fn cosines_by_chunk_ids<'env>(
        &self,
        env: &'env Env,
        ids: Value,
        query: Vec<f64>,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            let ids: Vec<u64> = required(ids, "cosinesByChunkIds ids")?;
            s.cosines_by_chunk_ids(&ids, &query)
        })
    }

    /// `countStaleChunks({ sourceId?, signature?, includeNullSignature? }?)`.
    #[napi]
    pub fn count_stale_chunks<'env>(
        &self,
        env: &'env Env,
        options: Option<Value>,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            s.count_stale_chunks(&arg(options, "countStaleChunks options")?)
        })
    }

    /// `sumStaleChunkChars({ sourceId?, signature?, includeNullSignature? }?)`.
    #[napi]
    pub fn sum_stale_chunk_chars<'env>(
        &self,
        env: &'env Env,
        options: Option<Value>,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            s.sum_stale_chunk_chars(&arg(options, "sumStaleChunkChars options")?)
        })
    }

    /// `listStaleChunks({ batchSize?, afterPageId?, afterChunkIndex?, sourceId?, orderBy?,
    /// afterUpdatedAt? }?)`: one keyset page of stale chunks.
    #[napi]
    pub fn list_stale_chunks<'env>(
        &self,
        env: &'env Env,
        options: Option<Value>,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            s.list_stale_chunks(&arg(options, "listStaleChunks options")?)
        })
    }

    /// `setPageEmbeddingSignature(slug, { sourceId?, signature })`.
    #[napi]
    pub fn set_page_embedding_signature<'env>(
        &self,
        env: &'env Env,
        slug: String,
        options: Value,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            let options = required(options, "setPageEmbeddingSignature options")?;
            s.set_page_embedding_signature(&slug, &options)
        })
    }

    /// `invalidateStaleSignatureEmbeddings({ signature, sourceId?, includeNullSignature? })`:
    /// drops the vectors outside the target space; returns how many.
    #[napi]
    pub fn invalidate_stale_signature_embeddings<'env>(
        &self,
        env: &'env Env,
        options: Value,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            let options = required(options, "invalidateStaleSignatureEmbeddings options")?;
            s.invalidate_stale_signature_embeddings(&options)
        })
    }

    /// `invalidateContentDriftEmbeddings({ sourceId? }?)`: drops the vectors whose text changed;
    /// returns how many.
    #[napi]
    pub fn invalidate_content_drift_embeddings<'env>(
        &self,
        env: &'env Env,
        options: Option<Value>,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            s.invalidate_content_drift_embeddings(&arg(
                options,
                "invalidateContentDriftEmbeddings options",
            )?)
        })
    }

    /// `readEmbeddingStateCounts({ mode, sourceIds?, purgeWindowHours })`.
    #[napi]
    pub fn read_embedding_state_counts<'env>(
        &self,
        env: &'env Env,
        options: Value,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            let options = required(options, "readEmbeddingStateCounts options")?;
            s.read_embedding_state_counts(&options)
        })
    }

    /// `listEmbeddingStateRows({ sourceIds?, slugs?, states, limit, purgeWindowHours })`.
    #[napi]
    pub fn list_embedding_state_rows<'env>(
        &self,
        env: &'env Env,
        options: Value,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            let options = required(options, "listEmbeddingStateRows options")?;
            s.list_embedding_state_rows(&options)
        })
    }

    /// `getChunksWithEmbeddings(slug, { sourceId?, includeUnsealed? }?)`: chunk rows with their
    /// vectors.
    #[napi]
    pub fn get_chunks_with_embeddings<'env>(
        &self,
        env: &'env Env,
        slug: String,
        options: Option<Value>,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            s.get_chunks_with_embeddings(&slug, &arg(options, "getChunksWithEmbeddings options")?)
        })
    }

    /// `updateTakeEmbeddings(rows)`: stores the vectors of active takes whose claim is unchanged;
    /// returns how many.
    #[napi]
    pub fn update_take_embeddings<'env>(
        &self,
        env: &'env Env,
        rows: Value,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            let rows: Vec<TakeEmbeddingInput> = required(rows, "updateTakeEmbeddings rows")?;
            s.update_take_embeddings(&rows)
        })
    }

    /// `getTakeEmbeddings(ids)`: `[{ id, embedding }]` for the takes with a current vector.
    #[napi]
    pub fn get_take_embeddings<'env>(
        &self,
        env: &'env Env,
        ids: Value,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            let ids: Vec<u64> = required(ids, "getTakeEmbeddings ids")?;
            s.get_take_embeddings(&ids)
        })
    }

    /// `countStaleTakes({ sourceId?, model?, dims? }?)`.
    #[napi]
    pub fn count_stale_takes<'env>(
        &self,
        env: &'env Env,
        options: Option<Value>,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            s.count_stale_takes(&arg(options, "countStaleTakes options")?)
        })
    }

    /// `listStaleTakes({ sourceId?, model?, dims? }?)`: `[{ take_id, page_slug, row_num, claim }]`.
    #[napi]
    pub fn list_stale_takes<'env>(
        &self,
        env: &'env Env,
        options: Option<Value>,
    ) -> napi::Result<Object<'env>> {
        self.run(env, move |s| {
            s.list_stale_takes(&arg(options, "listStaleTakes options")?)
        })
    }
}
